package com.namazteam.lux;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.webkit.*;import android.net.Uri;import android.graphics.Color;import android.hardware.*;import android.location.*;import org.json.*;import org.jsoup.*;import org.jsoup.nodes.*;import org.jsoup.select.*;import java.util.*;import java.text.*;import java.util.concurrent.*;

public class MainActivity extends Activity implements SensorEventListener {
 WebView web; SensorManager sensors; LocationManager locations; android.content.SharedPreferences prefs; ExecutorService pool=Executors.newFixedThreadPool(2); double lat=Double.NaN,lon=Double.NaN; boolean wantsCompass=false; float declination=0; int accuracy=0; long lastSensor=0;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(10,10,12));getWindow().setNavigationBarColor(Color.rgb(10,10,12));prefs=getSharedPreferences("lux",0);sensors=(SensorManager)getSystemService(SENSOR_SERVICE);locations=(LocationManager)getSystemService(LOCATION_SERVICE);web=new WebView(this);web.setBackgroundColor(Color.rgb(10,10,12));web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);WebView.setWebContentsDebuggingEnabled(false);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){openExternal(r.getUrl().toString());return true;}});setContentView(web);PrayerReceiver.channel(this);web.loadUrl("file:///android_asset/index.html");}
 void js(String fn,Object data){final String script=fn+"("+JSONObject.quote(String.valueOf(data))+")";runOnUiThread(()->web.evaluateJavascript(script,null));}
 void openExternal(String s){try{Uri u=Uri.parse(s);if(!"https".equals(u.getScheme()))return;startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){js("nativeMessage","Bağlantıyı açacak uygulama bulunamadı.");}}
 class Bridge {
  @JavascriptInterface public void loadTimes(String path,String city){prefs.edit().putString("requestedPath",path).apply();pool.execute(()->{try{if(!path.matches("/tr-TR/[0-9]+/[a-zA-Z0-9-]+"))throw new Exception();String url="https://namazvakitleri.diyanet.gov.tr"+path;Document doc=Jsoup.connect(url).userAgent("Mozilla/5.0 (Android) NamazTeamLux/0.1").timeout(25000).get();JSONArray days=new JSONArray();HashSet<String> seen=new HashSet<>();for(Element row:doc.select("table.vakit-table tbody tr")){Elements c=row.select("td");if(c.size()<8)continue;String raw=c.get(0).text();String[] a=raw.split(" ");if(a.length<3)continue;String[] months={"Ocak","Şubat","Mart","Nisan","Mayıs","Haziran","Temmuz","Ağustos","Eylül","Ekim","Kasım","Aralık"};int m=Arrays.asList(months).indexOf(a[1])+1;if(m<1)continue;String date=String.format(Locale.US,"%s-%02d-%02d",a[2],m,Integer.parseInt(a[0]));if(!seen.add(date))continue;JSONArray times=new JSONArray();boolean valid=true;for(int i=2;i<8;i++){String t=c.get(i).text();if(!t.matches("([01][0-9]|2[0-3]):[0-5][0-9]"))valid=false;times.put(t);}if(valid)days.put(new JSONObject().put("date",date).put("label",raw).put("hijri",c.get(1).text()).put("times",times));}if(days.length()==0)throw new Exception("Veri biçimi değişmiş olabilir");java.util.ArrayList<JSONObject> sorted=new java.util.ArrayList<>();for(int z=0;z<days.length();z++)sorted.add(days.getJSONObject(z));java.util.Collections.sort(sorted,(a,b)->a.optString("date").compareTo(b.optString("date")));days=new JSONArray(sorted);JSONObject result=new JSONObject().put("days",days).put("city",city).put("path",path).put("source",url).put("fetched",System.currentTimeMillis());if(!path.equals(prefs.getString("requestedPath",path)))return;prefs.edit().putString("data",result.toString()).apply();PrayerReceiver.schedule(MainActivity.this);js("receiveTimes",result.toString());}catch(Exception e){js("timesError","Diyanet'e ulaşılamadı. Yalnızca önceden alınmış, tarihi geçerli vakitler kullanılabilir.");}});}
  @JavascriptInterface public String cachedTimes(){return prefs.getString("data","");}
  @JavascriptInterface public void regions(String kind,int country,int state){pool.execute(()->{try{String u="https://namazvakitleri.diyanet.gov.tr/tr-TR/home/GetRegList?ChangeType="+("country".equals(kind)?"country":"state")+"&CountryId="+country+"&StateId="+state+"&Culture=tr-TR";String data=Jsoup.connect(u).ignoreContentType(true).timeout(20000).get().body().text();JSONObject result=new JSONObject(data).put("requestedState",state);js("receiveRegions",result.toString());}catch(Exception e){js("regionError","Konum listesi alınamadı. İnternet bağlantısını kontrol edin.");}});}
  @JavascriptInterface public void notifyConfig(String json){try{new JSONObject(json);prefs.edit().putString("settings",json).apply();}catch(Exception e){return;}runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);else PrayerReceiver.schedule(MainActivity.this);js("notificationStatus",status());});}
  @JavascriptInterface public String status(){try{JSONObject s=new JSONObject();s.put("granted",((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).areNotificationsEnabled());s.put("exact",Build.VERSION.SDK_INT<31||((AlarmManager)getSystemService(ALARM_SERVICE)).canScheduleExactAlarms());s.put("scheduled",prefs.getInt("scheduled",0));return s.toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public void exactSettings(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=31)startActivity(new Intent("android.settings.REQUEST_SCHEDULE_EXACT_ALARM",Uri.parse("package:"+getPackageName())));});}
  @JavascriptInterface public void appSettings(){runOnUiThread(()->startActivity(new Intent("android.settings.APP_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",getPackageName())));}
  @JavascriptInterface public void testNotification(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);return;}PrayerReceiver.show(MainActivity.this,"Bildirim denemesi","Namaz Team Lux bildirimleri hazır.");});}
  @JavascriptInterface public void compass(boolean active){wantsCompass=active;runOnUiThread(()->{if(!active){sensors.unregisterListener(MainActivity.this);return;}Sensor s=sensors.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);if(s==null)js("compassError","Bu cihazda pusula için gerekli dönüş sensörü yok.");else sensors.registerListener(MainActivity.this,s,SensorManager.SENSOR_DELAY_UI);});}
  @JavascriptInterface public void locate(){runOnUiThread(()->getLocation());}
  @JavascriptInterface public void vibrate(){try{((Vibrator)getSystemService(VIBRATOR_SERVICE)).vibrate(VibrationEffect.createOneShot(24,60));}catch(Exception e){}}
  @JavascriptInterface public void external(String u){runOnUiThread(()->openExternal(u));}
  @JavascriptInterface public void systemTheme(boolean light){runOnUiThread(()->{getWindow().setStatusBarColor(light?Color.rgb(248,245,238):Color.rgb(10,10,12));getWindow().setNavigationBarColor(light?Color.rgb(248,245,238):Color.rgb(10,10,12));getWindow().getDecorView().setSystemUiVisibility(light?android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR:0);});}
 }
 void getLocation(){if(checkSelfPermission("android.permission.ACCESS_FINE_LOCATION")!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission("android.permission.ACCESS_COARSE_LOCATION")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.ACCESS_FINE_LOCATION","android.permission.ACCESS_COARSE_LOCATION"},8);return;}try{String provider=locations.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:LocationManager.NETWORK_PROVIDER;if(!locations.isProviderEnabled(provider)){js("compassError","Telefonun konum hizmetini açın ve yeniden deneyin.");return;}LocationListener listener=new LocationListener(){public void onLocationChanged(Location l){lat=l.getLatitude();lon=l.getLongitude();GeomagneticField f=new GeomagneticField((float)lat,(float)lon,(float)l.getAltitude(),System.currentTimeMillis());declination=f.getDeclination();js("receiveLocation",lat+","+lon+","+l.getAccuracy());locations.removeUpdates(this);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}};locations.requestLocationUpdates(provider,0,0,listener);new Handler().postDelayed(()->{locations.removeUpdates(listener);if(Double.isNaN(lat))js("compassError","Konum alınamadı. Açık alanda yeniden deneyin.");},30000);}catch(Exception e){js("compassError","Konum alınamadı. Konum iznini kontrol edin.");}}
 public void onSensorChanged(SensorEvent e){if(e.timestamp-lastSensor<100000000)return;lastSensor=e.timestamp;float[] r=new float[9],v=new float[3];SensorManager.getRotationMatrixFromVector(r,e.values);SensorManager.getOrientation(r,v);float deg=(float)((Math.toDegrees(v[0])+declination+360)%360);js("receiveHeading",deg+","+accuracy);}
 public void onAccuracyChanged(Sensor s,int a){accuracy=a;}
 public void onRequestPermissionsResult(int req,String[] p,int[] results){super.onRequestPermissionsResult(req,p,results);if(req==8){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)getLocation();else if(results.length>1&&results[1]==PackageManager.PERMISSION_GRANTED)getLocation();else js("compassError","Konum izni verilmedi. Kıble yönü belirlenemiyor.");}if(req==7){PrayerReceiver.schedule(this);js("notificationStatus",new Bridge().status());}}
 protected void onResume(){super.onResume();if(web!=null){PrayerReceiver.schedule(this);js("notificationStatus",new Bridge().status());if(wantsCompass)new Bridge().compass(true);}}
 protected void onPause(){sensors.unregisterListener(this);super.onPause();}
 public void onBackPressed(){web.evaluateJavascript("back()",null);}
}
